```python
import json
import os
import urllib.request
from datetime import datetime, timedelta
import boto3
from botocore.exceptions import ClientError


def get_cost_analysis(ce_client):
    end_date = datetime.utcnow().date()
    start_date = end_date - timedelta(days=30)

    try:
        response = ce_client.get_cost_and_usage(
            TimePeriod={
                'Start': start_date.isoformat(),
                'End': end_date.isoformat()
            },
            Granularity='DAILY',
            Metrics=['UnblendedCost'],
            GroupBy=[{'Type': 'DIMENSION', 'Key': 'SERVICE'}]
        )

        total_cost = 0.0
        service_costs = {}
        for result in response.get('ResultsByTime', []):
            for group in result.get('Groups', []):
                amount = float(group['Metrics']['UnblendedCost']['Amount'])
                service = group['Keys'][0]
                service_costs[service] = service_costs.get(service, 0.0) + amount
                total_cost += amount

        return {
            "total_30d_usd": round(total_cost, 2),
            "by_service": {k: round(v, 2) for k, v in service_costs.items()}
        }
    except Exception as e:
        return {"error": str(e)}


def get_iam_data(iam_client):
    policies = []
    try:
        policies = iam_client.list_policies(Scope='Local', MaxItems=100)['Policies']
    except Exception:
        pass

    access_keys = []
    try:
        users = iam_client.list_users(MaxItems=100)['Users']
        for user in users:
            username = user['UserName']
            keys = iam_client.list_access_keys(UserName=username)['AccessKeyMetadata']
            for key in keys:
                access_keys.append({
                    "user": username,
                    "access_key_id": key['AccessKeyId'],
                    "status": key['Status'],
                    "create_date": key['CreateDate'].isoformat(),
                    "age_days": (datetime.utcnow() - key['CreateDate']).days
                })
    except Exception:
        pass

    return {
        "policy_count": len(policies),
        "policies": policies[:10],  # limit size
        "access_keys": access_keys
    }


def get_security_group_findings(ec2_client):
    findings = []
    try:
        sgs = ec2_client.describe_security_groups()['SecurityGroups']
        for sg in sgs:
            sg_id = sg['GroupId']
            for perm in sg.get('IpPermissions', []):
                for ip_range in perm.get('IpRanges', []):
                    if ip_range.get('CidrIp') == '0.0.0.0/0':
                        findings.append({
                            "security_group_id": sg_id,
                            "port_range": f"{perm.get('FromPort', 'All')}-{perm.get('ToPort', 'All')}",
                            "protocol": perm.get('IpProtocol', '-1')
                        })
    except Exception:
        pass
    return findings


def lambda_handler(event, context):
    ce_client = boto3.client('ce')
    iam_client = boto3.client('iam')
    ec2_client = boto3.client('ec2')

    report = {
        "timestamp": datetime.utcnow().isoformat(),
        "account_id": boto3.client('sts').get_caller_identity().get('Account'),
        "cost_analysis": get_cost_analysis(ce_client),
        "iam": get_iam_data(iam_client),
        "security_findings": {
            "open_ingress_rules": get_security_group_findings(ec2_client)
        },
        "summary": "Infrastructure cost and security posture report"
    }

    # Send to monitoring API
    try:
        data = json.dumps(report).encode('utf-8')
        req = urllib.request.Request(
            os.environ['MONITORING_API_URL'],
            data=data,
            headers={'Content-Type': 'application/json'},
            method='POST'
        )
        with urllib.request.urlopen(req) as response:
            status = response.getcode()
        print(f"Report sent successfully. Status: {status}")

        return {
            "statusCode": 200,
            "body": json.dumps({"message": "Report sent", "status": status})
        }
    except Exception as e:
        print(f"Failed to send report: {str(e)}")
        return {
            "statusCode": 500,
            "body": json.dumps({"error": str(e)})
        }
```

